from collections import defaultdict
from dataclasses import dataclass, field


@dataclass
class Book:
    book_id: str
    title: str
    borrower: str | None = None  # the member's name, None while on the shelf


@dataclass
class Member:
    LIMIT = 3
    books: list[Book] = field(default_factory=list)

    def can_borrow(self) -> bool:
        return len(self.books) < Member.LIMIT

    def titles(self) -> str:
        return " ".join(book.title for book in self.books) or "none"


class Library:
    def __init__(self) -> None:
        self.books: dict[str, Book] = {}
        # A member joins the first time their name comes up.
        self.members: defaultdict[str, Member] = defaultdict(Member)

    def add_book(self, book: Book) -> None:
        self.books[book.book_id] = book

    def lend(self, book_id: str, name: str) -> str:
        book = self.books[book_id]
        member = self.members[name]
        if book.borrower is not None:
            return "unavailable"
        if not member.can_borrow():
            return "limit reached"
        book.borrower = name
        member.books.append(book)
        return "lent"

    def give_back(self, book_id: str) -> str:
        book = self.books[book_id]
        if book.borrower is None:
            return "not lent"
        self.members[book.borrower].books.remove(book)
        book.borrower = None
        return "returned"

    def books_of(self, name: str) -> str:
        return self.members[name].titles()


