class Book {
public:
    Book(std::string id, std::string title) : id_(std::move(id)), title_(std::move(title)) {}

    const std::string& id() const { return id_; }
    const std::string& title() const { return title_; }
    // The member's name, empty while the book is on the shelf.
    const std::string& borrower() const { return borrower_; }
    void setBorrower(const std::string& name) { borrower_ = name; }

private:
    std::string id_;
    std::string title_;
    std::string borrower_;
};

class Member {
public:
    static constexpr std::size_t kLimit = 3;

    bool canBorrow() const { return books_.size() < kLimit; }
    void borrow(Book* book) { books_.push_back(book); }
    void giveBack(Book* book) { books_.erase(std::find(books_.begin(), books_.end(), book)); }

    std::string titles() const {
        std::string out;
        for (const Book* book : books_) {
            out += (out.empty() ? "" : " ") + book->title();
        }
        return out.empty() ? "none" : out;
    }

private:
    std::vector<Book*> books_; // in the order lent
};

class Library {
public:
    void addBook(const Book& book) { books_.emplace(book.id(), book); }

    std::string lend(const std::string& id, const std::string& name) {
        Book& book = books_.at(id);
        Member& member = members_[name];
        if (!book.borrower().empty()) {
            return "unavailable";
        }
        if (!member.canBorrow()) {
            return "limit reached";
        }
        book.setBorrower(name);
        member.borrow(&book);
        return "lent";
    }

    std::string giveBack(const std::string& id) {
        Book& book = books_.at(id);
        if (book.borrower().empty()) {
            return "not lent";
        }
        members_[book.borrower()].giveBack(&book);
        book.setBorrower("");
        return "returned";
    }

    std::string booksOf(const std::string& name) { return members_[name].titles(); }

private:
    std::map<std::string, Book> books_;
    std::map<std::string, Member> members_;
};

int main() {
    int q;
    std::cin >> q;
    Library library;
    for (int i = 0; i < q; i++) {
        std::string op, a, b;
        std::cin >> op >> a;
