package main

import (
	"fmt"
	"strings"
)

type Book struct {
	id       string
	title    string
	borrower string // the member's name, "" while on the shelf
}

const limit = 3

// Member holds the books they borrowed, in the order lent.
type Member struct {
	books []*Book
}

func (m *Member) canBorrow() bool {
	return len(m.books) < limit
}

func (m *Member) giveBack(book *Book) {
	for i, held := range m.books {
		if held == book {
			m.books = append(m.books[:i], m.books[i+1:]...)
			return
		}
	}
}

func (m *Member) titles() string {
	if len(m.books) == 0 {
		return "none"
	}
	titles := make([]string, len(m.books))
	for i, book := range m.books {
		titles[i] = book.title
	}
	return strings.Join(titles, " ")
}

// Library lends books to members and takes them back.
type Library struct {
	books   map[string]*Book
	members map[string]*Member
}

func newLibrary() *Library {
	return &Library{books: map[string]*Book{}, members: map[string]*Member{}}
}

func (l *Library) member(name string) *Member {
	if l.members[name] == nil {
		l.members[name] = &Member{}
	}
	return l.members[name]
}

func (l *Library) addBook(book *Book) {
	l.books[book.id] = book
}

func (l *Library) lend(id, name string) string {
	book, member := l.books[id], l.member(name)
	if book.borrower != "" {
		return "unavailable"
	}
	if !member.canBorrow() {
		return "limit reached"
	}
	book.borrower = name
	member.books = append(member.books, book)
	return "lent"
}

func (l *Library) giveBack(id string) string {
	book := l.books[id]
	if book.borrower == "" {
		return "not lent"
	}
	l.member(book.borrower).giveBack(book)
	book.borrower = ""
	return "returned"
}

func (l *Library) booksOf(name string) string {
	return l.member(name).titles()
}

